WITH filtered AS (SELECT id, session_id, event_type, page, duration_sec, CEIL(duration_sec) AS duration_sec_whole, COALESCE(page, 'UNKNOWN') AS page_clean FROM web_events WHERE page IS NOT NULL), metrics AS (SELECT *, DENSE_RANK() OVER (PARTITION BY session_id, event_type ORDER BY duration_sec DESC) AS duration_sec_dense_rank, LAG(duration_sec, 2) OVER (PARTITION BY page, event_type ORDER BY duration_sec_whole, id) AS prev_duration_sec, LAST_VALUE(duration_sec_whole) IGNORE NULLS OVER (PARTITION BY event_type ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_duration_sec_whole FROM filtered), enriched AS (SELECT *, NTILE(4) OVER (PARTITION BY event_type ORDER BY prev_duration_sec DESC, id) AS prev_duration_sec_bucket, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY duration_sec, id) AS row_seq, ROW_NUMBER() OVER (PARTITION BY page ORDER BY prev_duration_sec DESC, id) AS seq_no FROM metrics), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY page, event_type ORDER BY duration_sec_dense_rank NULLS FIRST, id) AS row_num FROM enriched) t WHERE row_num = 1), scored AS (SELECT *, NTILE(10) OVER (PARTITION BY session_id, page ORDER BY row_seq DESC, id) AS row_seq_bucket, LEAD(row_seq, 1) OVER (ORDER BY prev_duration_sec, id) AS next_row_seq FROM ranked), ranked_web_events AS (SELECT *, RANK() OVER (PARTITION BY session_id ORDER BY duration_sec_whole NULLS FIRST) AS rn FROM scored QUALIFY rn = 1), base AS (SELECT id, event_type, page, duration_sec, page_clean, duration_sec_dense_rank, prev_duration_sec, last_known_duration_sec_whole, row_seq, seq_no, row_seq_bucket, next_row_seq, FLOOR(seq_no) AS seq_no_whole, row_num + last_known_duration_sec_whole AS row_num_plus_last_known_duration_sec_whole, COALESCE(page, 'N/A') AS resolved_page FROM ranked_web_events WHERE row_seq > 4) SELECT id, duration_sec, page_clean, duration_sec_dense_rank, prev_duration_sec, last_known_duration_sec_whole, seq_no, row_seq_bucket, next_row_seq FROM base ORDER BY prev_duration_sec
